static uint32_t xorshift32(uint32_t* state) {
    uint32_t x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    *state = x;
    return x;
}

struct RGB random_pixel(struct PpmWriter* w, int32_t size, uint32_t seed) {
