    int32_t max_val = 255;
    int32_t r = (int32_t)(xorshift32(&state) % (max_val + 1));
    int32_t g = (int32_t)(xorshift32(&state) % (max_val + 1));
    int32_t b = (int32_t)(xorshift32(&state) % (max_val + 1));
    return {(uint8_t)r, (uint8_t)g, (uint8_t)b};
}

