static uint32_t xorshift32(uint32_t* state) {
    uint32_t x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    *state = x;
    return x;
}

struct RGB gradient_pixel(int32_t x, int32_t y, int32_t size) {
    int32_t max_coord = (size == 1) ? 1 : (size - 1);
    int32_t r = x * 255 / max_coord;
    int32_t g = (max_coord - y) * 255 / max_coord;
    return (struct RGB){(uint8_t)r, (uint8_t)g, 0};
}

struct RGB checker_pixel(int32_t x, int32_t y, int32_t size) {
    (void)size;
    int32_t v = ((x + y) % 2 == 0) ? 255 : 0;
    return (struct RGB){(uint8_t)v, (uint8_t)v, (uint8_t)v};
}

struct RGB radial_pixel(int32_t x, int32_t y, int32_t size) {
    double cx = (size - 1) / 2.0;
    double cy = (size - 1) / 2.0;
    double max_dist = sqrt(cx * cx + cy * cy);
    double dx = x - cx;
    double dy = y - cy;
    double dist = sqrt(dx * dx + dy * dy);
    double hue = (max_dist > 0.0) ? (dist / max_dist) * 360.0 : 0.0;
    return hsv_to_rgb(hue, 1.0, 1.0);
}

struct RGB random_pixel(uint32_t* state) {
    int32_t max_val = 255;
    uint8_t r = (uint8_t)(xorshift32(state) % (max_val + 1));
    uint8_t g = (uint8_t)(xorshift32(state) % (max_val + 1));
    uint8_t b = (uint8_t)(xorshift32(state) % (max_val + 1));
    return (struct RGB){r, g, b};
}

struct RGB pattern_pixel(enum Pattern p, int32_t x, int32_t y, int32_t size) {
    switch (p) {
    case PATTERN_GRADIENT:
        return gradient_pixel(x, y, size);
    case PATTERN_CHECKER:
        return checker_pixel(x, y, size);
    case PATTERN_RADIAL:
        return radial_pixel(x, y, size);
    default:
        return (struct RGB){0, 0, 0};
    }
}
```

