    double y = luma(p.r, p.g, p.b);
    uint8_t yb = static_cast<uint8_t>(y + 0.5);
    return {yb, yb, yb};
}

Pixel pixel_threshold(const Pixel& p, int threshold) {
    double y = luma(p.r, p.g, p.b);
    return (y > threshold) ? Pixel{255, 255, 255} : Pixel{0, 0, 0};
}

void apply_grayscale(Image& img) {
